#include <Aevrynd/WorldStreamer3D.h>
#include <chrono>
#include <iostream>

using namespace Aevrynd;
int main(){
    if(!(WorldStreamer3D::CoordinateAt({-1,0,-33},32)==WorldChunkCoordinate3D{-1,-2})){std::cerr<<"Negative world coordinate mapping failed\n";return 1;}
    WorldStreamer3D streamer({32,1,2,2,3,0x1234u});WorldStreamingStats3D stats=streamer.Update({0,0,0});if(stats.residentChunks!=2||stats.queuedChunks!=7||stats.lastLoaded!=2||streamer.LoadedChunks().size()!=2||!streamer.UnloadedChunks().empty()){std::cerr<<"Load budget failed\n";return 2;}for(int index=0;index<4;++index)stats=streamer.Update({0,0,0});if(stats.residentChunks!=9||stats.queuedChunks||!streamer.Contains({-1,-1})||!streamer.Contains({1,1})){std::cerr<<"Initial residency failed\n";return 3;}
    const uint32_t stableSeed=WorldStreamer3D::ChunkSeed({4,-7},0x1234u);for(int index=0;index<8;++index)stats=streamer.Update({320,0,-320});if(stats.observerChunk!=WorldChunkCoordinate3D{10,-10}||stats.residentChunks!=9||stats.lastUnloaded>3||stats.totalUnloaded<9||WorldStreamer3D::ChunkSeed({4,-7},0x1234u)!=stableSeed){std::cerr<<"Teleport streaming failed\n";return 4;}
    constexpr int Iterations=20000;const auto start=std::chrono::steady_clock::now();for(int index=0;index<Iterations;++index)streamer.Update({float((index%200)-100)*5.f,0,float(((index*7)%200)-100)*5.f});const uint64_t averageNanoseconds=uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count())/Iterations;if(averageNanoseconds>500000){std::cerr<<"Streaming update budget failed\n";return 5;}
    stats=streamer.Stats();streamer.Configure({32,24,28,128,128,0x1234u});streamer.Configure({32,1,2,2,3,0x1234u});const ReusableMemoryStats expandedMemory=streamer.MemoryStats();const std::size_t releasedBytes=streamer.TrimUnusedMemory();const ReusableMemoryStats trimmedMemory=streamer.MemoryStats();const WorldStreamingStats3D reusedStats=streamer.Update({0,0,0});if(!expandedMemory.reclaimableCapacityBytes||!releasedBytes||trimmedMemory.retainedCapacityBytes>=expandedMemory.retainedCapacityBytes||trimmedMemory.reclaimableCapacityBytes||trimmedMemory.lastReleasedBytes!=releasedBytes||trimmedMemory.trimCount!=1||reusedStats.residentChunks!=2||streamer.LoadedChunks().size()!=2){std::cerr<<"Streaming workspace memory recovery failed\n";return 6;}
    std::cout<<"resident="<<stats.residentChunks<<" peak="<<stats.peakResidentChunks<<" loaded="<<stats.totalLoaded<<" unloaded="<<stats.totalUnloaded<<" averageNs="<<averageNanoseconds<<" released="<<releasedBytes<<'\n';return 0;
}
